two_sum_sorted:
def two_sum_sorted(a, target):
    left, right = 0, len(a) - 1
    while left < right:
        total = a[left] + a[right]
        if total == target:
            return [left, right]
        if total < target:
            left += 1
        else:
            right -= 1
    return []

binary_search:
def binary_search(a, target):
    left, right = 0, len(a) - 1
    while left <= right:
        mid = (left + right) // 2
        if a[mid] == target:
            return mid
        if a[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

max_subarray:
def max_subarray(a):
    best = current = a[0]
    for x in a[1:]:
        current = max(x, current + x)
        best = max(best, current)
    return best

prefix_sums:
def prefix_sums(a):
    prefix = [0]
    for value in a:
        prefix.append(prefix[-1] + value)
    return prefix

bubble_sort:
def bubble_sort(a):
    for end in range(len(a) - 1, 0, -1):
        swapped = False
        for j in range(end):
            if a[j] > a[j + 1]:
                a[j], a[j + 1] = a[j + 1], a[j]
                swapped = True
        if not swapped:
            break
    return a

selection_sort:
def selection_sort(a):
    for i in range(len(a) - 1):
        low = i
        for j in range(i + 1, len(a)):
            if a[j] < a[low]:
                low = j
        a[i], a[low] = a[low], a[i]
    return a

insertion_sort:
def insertion_sort(a):
    for i in range(1, len(a)):
        j = i
        while j > 0 and a[j - 1] > a[j]:
            a[j - 1], a[j] = a[j], a[j - 1]
            j -= 1
    return a

merge_sort:
def merge_sort(a, lo=0, hi=None):
    if hi is None:
        hi = len(a)
    if hi - lo < 2:
        return a
    mid = (lo + hi) // 2
    merge_sort(a, lo, mid)
    merge_sort(a, mid, hi)

    # Merge in place
    left, right = lo, mid
    while left < right < hi:
        if a[left] > a[right]:
            a.insert(left, a.pop(right))
            right += 1
        left += 1
    return a

quick_sort:
def quick_sort(a, lo=0, hi=None):
    if hi is None:
        hi = len(a) - 1
    if lo >= hi:
        return a
    pivot = a[hi]
    small = lo
    for j in range(lo, hi):
        if a[j] < pivot:
            a[small], a[j] = a[j], a[small]
            small += 1
    a[small], a[hi] = a[hi], a[small]
    quick_sort(a, lo, small - 1)
    quick_sort(a, small + 1, hi)
    return a

heap_sort:
def sift_down(a, top, end):
    while 2 * top + 1 < end:
        kid = 2 * top + 1
        other = kid + 1
        if other < end and a[other] > a[kid]:
            kid = other
        if a[kid] <= a[top]:
            return
        a[top], a[kid] = a[kid], a[top]
        top = kid

def heap_sort(a):
    first = len(a) // 2 - 1
    for start in range(first, -1, -1):
        sift_down(a, start, len(a))
    for end in range(len(a) - 1, 0, -1):
        a[0], a[end] = a[end], a[0]
        sift_down(a, 0, end)
    return a
